Response:

```latex
\documentclass{standalone}
\usepackage{tikz}
\usepackage{pgfplots}
\pgfplotsset{compat=1.16}

\begin{document}
\begin{tikzpicture}
    \begin{axis}[
        xmin=-1, xmax=5,
        ymin=-1, ymax=5,
        axis lines=middle,
        xlabel={$x$}, ylabel={$y$},
        enlargelimits={abs=0.5},
        axis line style={latex-latex},
        tick label style={font=\scriptsize},
        xmajorgrids, ymajorgrids,
        grid style={dashed, gray!30},
        colormap/blackwhite,
        colorbar,
        colorbar style={
            at={(0.17,0.02)},
            anchor=south west,
            width=0.2,
            height=0.02,
            tick style={draw=none},
            yticklabel style={font=\scriptsize, text width=1.5em, align=right},
            ytick={0.5},
            yticklabels={Pale Red},
            point meta=explicit,
            point meta min=0, point meta max=1,
        },
        clip=false
    ]

    \addplot [
        only marks,
        mark=*,
        mark options={fill=black},
        nodes near coords,
        nodes near coords align={anchor=north},
        nodes near coords style={font=\scriptsize},
        point meta=0,
    ] coordinates {
        (1,1) [$x$],
        (2,2) [$y_1$],
        (3,3) [$y_2$],
        (4,4) [$y_3$]
    };

    \addplot [
        dashed,
        gray,
        domain=-1:5,
        restrict y to domain=-1:5
    ] {x} node[pos=0.5, above left, font=\scriptsize, text width=1.5em, align=center] {$x$};

    \addplot [
        fill=red!15,
        domain=1:5,
        ymin=1, ymax=5
    ] {0};

    \addplot [
        fill=red!15,
        domain=-1:4,
        xmin=1, xmax=5
    ] {0};

    \end{axis}
\end{tikzpicture}
\end{document}
```

